<template><section class="page"><PageHeader title="创建账号" :back="true"/><p class="text-2xl font-bold mt-8">开始你的健康记录</p><p class="muted text-sm mt-2">注册后可同步血糖、用药和饮食数据</p><form class="space-y-4 mt-7" @submit.prevent="submit"><label class="block text-sm font-medium">姓名<input v-model="name" class="w-full mt-2 p-4 rounded-xl border-0 bg-white" required placeholder="例如：张明"/></label><label class="block text-sm font-medium">手机号<input v-model="account" class="w-full mt-2 p-4 rounded-xl border-0 bg-white" required pattern="1[3-9]\d{9}" placeholder="11 位手机号"/></label><label class="block text-sm font-medium">设置密码<input v-model="password" class="w-full mt-2 p-4 rounded-xl border-0 bg-white" required minlength="6" type="password" placeholder="至少 6 位"/></label><label class="block text-sm font-medium">确认密码<input v-model="confirm" class="w-full mt-2 p-4 rounded-xl border-0 bg-white" required minlength="6" type="password" placeholder="再次输入密码"/></label><label class="flex items-start gap-2 text-xs muted"><input v-model="consent" required type="checkbox" class="accent-[#0a84ff] mt-0.5"/>我已阅读并同意用户协议和隐私政策。</label><p class="text-xs text-[#ff3b30] min-h-4">{{ error }}</p><button class="btn-primary">注册并开始记录</button></form><p class="text-center text-sm muted mt-6">已有账号？<RouterLink to="/login" class="text-[#0a84ff]">立即登录</RouterLink></p></section></template>
<script setup lang="ts">
import { ref } from 'vue';import { useRouter } from 'vue-router';import { useStore } from 'vuex';import PageHeader from '../components/PageHeader.vue';import type { RootState } from '../main';const router=useRouter();const store=useStore<RootState>();const name=ref('');const account=ref('');const password=ref('');const confirm=ref('');const consent=ref(false);const error=ref('');const loading=ref(false);async function submit(){const trimmedName=name.value.trim();const phone=account.value.trim();if(!trimmedName){error.value='请输入姓名';return}if(!/^1[3-9]\d{9}$/.test(phone)){error.value='请输入有效的 11 位手机号';return}if(password.value.length<6){error.value='密码至少 6 位';return}if(password.value!==confirm.value){error.value='两次密码不一致';return}if(!consent.value){error.value='请先同意用户协议和隐私政策';return}error.value='';loading.value=true;try{await store.dispatch('auth/register',{name:trimmedName,phone,password:password.value,consent:consent.value});router.push('/home')}catch(e){error.value=e instanceof Error?e.message:'注册失败，请稍后重试'}finally{loading.value=false}}</script>


